"""Reducer-only host. No timers, no processes, no wall clock in state.

The only computation is the Sigma-GLYPH hash-thunk reducer: lifecycle
predicates are SKI terms, every check returns a priced receipt, and the sum
of ATP spent is the only clock. Everything external (task bytes, witness
headers, private backup, filesystem listing, model answers) enters as an
event in an append-only log. State is canonical bytes addressed by hash:
a checkpoint is a state hash, resumption is folding the remaining events.

The model is a neutral oracle: its answer is an event, never code. The
host applies only the four closed actions of transplant-002.
"""
import base64
import hashlib
import json
import core
import gate
import sigma_glyph as sg
import triad_delivery as carrier

LOG_STREAM = 'f' * 64          # event-log stream (public headers)
PRIVATE_STREAM = 'e' * 64      # transplant-002 private-history stream
PREDICATE_ATP = 1000

def sha(b):
    return hashlib.sha256(b).hexdigest()

def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()

# ---------------------------------------------------------------- policy terms
def _church(flag):
    return sg.KG if flag else ('app', sg.KG, sg.IG)          # TRUE = K, FALSE = K I

def _lam(names, body):
    for name in reversed(names):
        body = ('lam', name, body)
    return body

def _lapp(*terms):
    out = terms[0]
    for t in terms[1:]:
        out = ('lapp', out, t)
    return out

def state_term(witnessed, recovered, written):
    """Lifecycle as a Church triple: \\f. f w r i."""
    return sg.c1(_lam(['f'], _lapp(('var', 'f'), _church(witnessed), _church(recovered), _church(written))))

# Which prerequisite each action demands, as a function of the triple.
POLICY = {
    'witness':         sg.c1(_lam(['s'], sg.KG)),
    'recover':         sg.c1(_lam(['s'], _lapp(('var', 's'), _lam(['w', 'r', 'i'], ('var', 'w'))))),
    'write_inventory': sg.c1(_lam(['s'], sg.KG)),
    'finish':          sg.c1(_lam(['s'], _lapp(('var', 's'), _lam(['w', 'r', 'i'], ('var', 'i'))))),
}
PREREQUISITE = {'recover': 'WITNESS_REQUIRED', 'finish': 'INVENTORY_REQUIRED'}

def _put_tree(store, t):
    if t[0] == 'app':
        _put_tree(store, t[1]); _put_tree(store, t[2])
    return store.put(sg.term_bytes(t))

def allowed(action, witnessed, recovered, written, atp=PREDICATE_ATP):
    """One priced reduction of POLICY[action] applied to the state triple."""
    store = sg.Store()
    h = _put_tree(store, ('app', POLICY[action], state_term(witnessed, recovered, written)))
    receipt = sg.eval_receipt(h, atp, store, sg.VERIFIER_LIMITS)
    result = receipt.result_hash
    if receipt.exit != 'normal_form':
        verdict = None
    elif result == sg.K_H:
        verdict = True
    elif result == sg.FALSE_H:
        verdict = False
    else:
        verdict = None
    return {'action': action, 'term': h.hex(), 'exit': receipt.exit,
            'result_hash': result.hex(), 'atp_spent': receipt.atp_spent, 'allowed': verdict}

# ---------------------------------------------------------------- event log
def event(kind, data):
    return {'kind': kind, 'sha256': sha(data), 'bytes': data}

def header_chain(events):
    """Public headers over event commitments; validates with core.headers_valid."""
    headers, previous = [], core.ZERO
    for n, e in enumerate(events, 1):
        body = {'stream': LOG_STREAM, 'seq': n, 'prev': previous,
                'commitment': core.digest('reducer.event.v0', {'kind': e['kind'], 'sha256': e['sha256']})}
        head = core.digest('triad.history.header.v0', body)
        headers.append(dict(body, head=head))
        previous = head
    core.headers_valid(headers, LOG_STREAM)
    return headers

# ---------------------------------------------------------------- state
def initial_state():
    return {'seq': 0, 'env': {}, 'witnessed': False, 'observed': None, 'recovered': False,
            'recovered_pages': None, 'written': False, 'inventory_sha256': None,
            'finished': False, 'atp_spent': 0, 'receipts': [], 'trace': []}

def state_hash(state):
    return sha(canonical(state))

def _need(state, cas, kind):
    digest = state['env'].get(kind)
    if digest is None:
        raise KeyError(kind)
    return cas[digest]

def apply(state, cas, ev, effects):
    """Pure transition on canonical state; `cas` maps sha256 -> bytes; `effects`
    receives (name, bytes) for the single permitted filesystem effect."""
    state = json.loads(canonical(state))
    state['seq'] += 1
    cas[ev['sha256']] = ev['bytes']
    if ev['kind'] != 'oracle':
        state['env'][ev['kind']] = ev['sha256']
        state['trace'].append({'event': ev['kind'], 'sha256': ev['sha256']})
        return state
    if state['finished']:
        state['trace'].append({'call': {'raw': ev['sha256']}, 'result': {'status': 'REFUSED', 'reason': 'FINISHED'}})
        return state
    task_bytes = _need(state, cas, 'input.task')
    prefix = json.loads(_need(state, cas, 'input.prefix'))
    expected_subject = sha(task_bytes)
    try:
        call = json.loads(json.loads(ev['bytes'])['message']['content'])
        assert isinstance(call, dict)
        action = call.get('action')
        if action not in POLICY:
            raise ValueError('TOOL_SHAPE')
        receipt = allowed(action, state['witnessed'], state['recovered'], state['written'])
        state['atp_spent'] += receipt['atp_spent']
        state['receipts'].append(receipt)
        if receipt['allowed'] is None:
            result = {'status': 'REFUSED', 'reason': 'KERNEL_' + receipt['exit'].upper()}
        elif receipt['allowed'] is False:
            result = {'status': 'REFUSED', 'reason': PREREQUISITE[action]}
        elif action == 'witness' and set(call) == {'action'}:
            observed = json.loads(_need(state, cas, 'observation.witness_store'))
            result = core.observe(prefix, observed, PRIVATE_STREAM)
            state['observed'] = observed
            state['witnessed'] = True
        elif action == 'recover' and set(call) == {'action'}:
            backup = json.loads(_need(state, cas, 'observation.private_backup'))
            pages = core.recover(prefix, backup, state['observed'], PRIVATE_STREAM)
            cap = gate.carrier.capsule(pages[-1]['text'].encode())
            exact_decision = base64.b64decode(cap['files'][0]['base64'])
            result = {'status': 'RECOVERED', 'subject': cap['subject'], 'private_page': exact_decision.decode()}
            state['recovered_pages'] = pages
            state['recovered'] = True
        elif action == 'write_inventory' and set(call) == {'action'}:
            inventory = json.loads(_need(state, cas, 'observation.inventory'))
            note = '# Source inventory\n\n' + '\n'.join(
                f"- {p['file']}: {p['bytes']} bytes; SHA-256 {p['sha256']}" for p in inventory) + '\n'
            digest = sha(note.encode())
            effects(f'inventory-{digest[:12]}.md', note.encode())
            state['inventory_sha256'] = digest
            state['written'] = True
            result = {'status': 'WRITTEN', 'sha256': digest, 'files': len(inventory)}
        elif action == 'finish' and set(call) == {'action', 'record_approval', 'reason'} \
                and type(call['record_approval']) is bool and isinstance(call['reason'], str):
            pages = state['recovered_pages'] if state['recovered'] else prefix
            eligibility = gate.check(task_bytes, expected_subject, pages, state['observed'],
                                     PRIVATE_STREAM, call['record_approval'])
            result = {'status': 'FINISHED', 'requested_record_approval': call['record_approval'],
                      'eligibility': eligibility}
            state['finished'] = True
        else:
            result = {'status': 'REFUSED', 'reason': 'TOOL_SHAPE'}
    except KeyError as missing:
        call = call if 'call' in dir() else {'raw': ev['sha256']}
        result = {'status': 'WAITING_OBSERVATION', 'reason': str(missing.args[0])}
    except (ValueError, TypeError, AssertionError):
        call = {'raw': ev['sha256']}
        result = {'status': 'REFUSED', 'reason': 'INVALID_JSON_CALL'}
    state['trace'].append({'call': call, 'result': result})
    return state

def fold(events, effects, state=None, cas=None):
    state = initial_state() if state is None else state
    cas = {} if cas is None else cas
    hashes = []
    for ev in events:
        state = apply(state, cas, ev, effects)
        hashes.append(state_hash(state))
    return state, cas, hashes
