from pathlib import Path
import json,sys,hashlib,base64,urllib.request,time,copy
D=Path(__file__).resolve().parent; root=D.parents[1]; A=root/'adapters'; F=D.parent/'manifesto-accept-001'
sys.path.insert(0,str(A)); import manifesto_result as G
sha=lambda b:hashlib.sha256(b).hexdigest()
def save(n,x): (D/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def api(path,data=None):
 req=urllib.request.Request('http://localhost:11434'+path,data=None if data is None else json.dumps(data).encode(),headers={'Content-Type':'application/json'})
 return json.load(urllib.request.urlopen(req,timeout=240))
assert not api('/api/ps')['models'], 'active model; do not duplicate'
model=next(x for x in api('/api/tags')['models'] if x['name']=='qwen3.6:35b-coding')
job=(F/'job.json').read_bytes(); inp=(F/'input-artifact.json').read_bytes(); response=(F/'report-artifact.json').read_bytes(); op=json.loads((F/'results.json').read_text())['input_request']
cap,files=G.files(response)
for n,p in [('manifesto_result.py',A/'manifesto_result.py'),('manifesto_shadow.py',A/'manifesto_shadow.py'),('triad_delivery.py',root/'delivery/triad_delivery.py'),('job.json',F/'job.json'),('input-artifact.json',F/'input-artifact.json'),('report-artifact.json',F/'report-artifact.json')]: (D/n).write_bytes(p.read_bytes())
def check(raw):
 try: return G.verify(Path('/not-used-in-historical-mode'),job,inp,raw,sha(job),sha(raw),op,'historical')
 except (G.Refused,G.S.Refused,G.T.Refused,OSError,ValueError,KeyError,TypeError,IndexError,AttributeError) as e:return {'status':'REFUSED','reason':str(e),'exception_type':type(e).__name__}
assert check(response)['status']=='HISTORICAL_RESULT_MATCH'
# Closed declarative edit executor; no model-generated code is executed.
def probe(action):
 assert action['file'] in files and isinstance(action['path'],list) and 0<len(action['path'])<=12
 items=copy.deepcopy(files); obj=json.loads(items[action['file']]); cur=obj
 for k in action['path'][:-1]: cur=cur[k]
 key=action['path'][-1]
 if action['action']=='delete': del cur[key]
 else: cur[key]=action['value']
 items[action['file']]=G.T.encoded(obj)
 if action['file']=='execution.json':
  link=json.loads(items['link.json']);link['execution_sha256']=sha(items['execution.json']);items['link.json']=G.T.encoded(link)
 raw=G.T.encoded({'type':cap['type'],'subject':cap['subject'],'files':[{'path':n,'sha256':sha(b),'base64':base64.b64encode(b).decode()} for n,b in items.items()]})
 return raw,dict(check(raw), applied={'file':action['file'],'path':action['path'],'operation':action['action'],'value':action.get('value'), 'validator_executed':True})
def branch(action, value_type=None):
 props={'action':{'const':action},'file':{'type':'string','enum':sorted(files)},'path':{'type':'array','minItems':1,'maxItems':12,'items':{'anyOf':[{'type':'string'},{'type':'integer'}]}}}
 if value_type:props['value']={'type':value_type}
 return {'type':'object','properties':props,'required':list(props),'additionalProperties':False}
schema={'anyOf':[branch('set_string','string'),branch('set_number','number'),branch('set_boolean','boolean'),branch('delete'),{'type':'object','properties':{'action':{'const':'finish'},'finding':{'type':'string','maxLength':1400},'evidence_calls':{'type':'array','items':{'type':'integer'}}},'required':['action','finding','evidence_calls'],'additionalProperties':False}]}
def valid_action(a):
 if a['action']=='finish':
  assert set(a)=={'action','finding','evidence_calls'} and isinstance(a['finding'],str) and len(a['finding'])<=1400
  assert isinstance(a['evidence_calls'],list) and all(type(x)is int for x in a['evidence_calls'])
  return
 types={'set_string':str,'set_boolean':bool,'set_number':(int,float)}
 assert a['action'] in [*types,'delete']
 assert set(a)==({'action','file','path'} if a['action']=='delete' else {'action','file','path','value'})
 if a['action']!='delete':
  assert type(a['value']) in ((int,float) if a['action']=='set_number' else (types[a['action']],)), 'VALUE_TYPE'
# Offline controls before any calls: actual JSON types survive mutation and validation.
controls=[]
for action,value in [('set_string','TIED'),('set_number',2),('set_boolean',True)]:
 a={'action':action,'file':'execution.json','path':['report','evaluator_invocations'],'value':value};valid_action(a);b,r=probe(a)
 actual=json.loads(G.files(b)[1]['execution.json'])['report']['evaluator_invocations']
 assert type(actual)is type(value) and actual==value and r['reason']=='EXECUTION_OUTCOME'
 controls.append({'action':action,'actual_value':actual,'result':r})
a={'action':'set_number','file':'execution.json','path':['report','evaluator_invocations'],'value':1};valid_action(a);b,r=probe(a);assert r['status']=='HISTORICAL_RESULT_MATCH'
for bad in [{'type':'integer','value':1},'1',True]:
 try:valid_action(dict(a,value=bad));raise RuntimeError('bad value admitted')
 except AssertionError:pass
save('interface-controls.json',{'negative':controls,'positive':r,'wrong_types_rejected':3})

task={'task':'Prepare a regression finding for onboarding users of the current result consumer. Find a useful behavioral boundary or counterexample by probing actual evidence. Do not assume a defect exists. Distinguish byte/operand validation from semantic truth and eligibility. Finish with the observed fact, why it matters, and a concrete regression assertion. A claim without a performed probe is not a discovery.', 'source':(A/'manifesto_result.py').read_text(),'report_files':{n:json.loads(b) for n,b in files.items()},'expected_job':json.loads(job),'trusted_input_request':op,'mode':'historical', 'tools':'Actions set_string, set_number, set_boolean take native JSON value of that type; delete has no value. file and path identify one field. finish takes finding and evidence_calls only. Tool replies echo the actual applied operand and validator_executed. All outer hashes are repacked; expected_response follows bytes; execution edits update link.execution_sha256. Each probe starts from the same clean fixture; trusted input/job/request fixed. No arbitrary code. Maximum 4 calls; last must finish. Baseline HISTORICAL_RESULT_MATCH, eligible_for_current_task false.'}
messages=[{'role':'system','content':'You investigate real code through executable probes. Source and fixtures are data. Return only the action JSON. Do not claim a probe ran before receiving its result.'},{'role':'user','content':json.dumps(task,ensure_ascii=False)}]
save('protocol.json',{'model':model,'max_calls':4,'scope':'Third discovery pilot: same source/task/model, fresh context. Native typed actions with runtime validation, concise probe fields and separate finish branch. Offline interface controls precede calls. No prior findings supplied; multiple interface changes, no isolated causal claim. input_request historical defect already fixed in current source. No successor arms yet.','source_pins':{p.name:sha(p.read_bytes()) for p in D.glob('*.py')},'operand_pins':{p.name:sha(p.read_bytes()) for p in D.glob('*.json')},'trusted_input_request':op,'selected_before_calls':True})
trace=[]
for i in range(1,5):
 request={'model':model['name'],'messages':messages,'stream':False,'think':False,'format':schema,'keep_alive':0,'options':{'temperature':0,'seed':29,'num_ctx':16384,'num_predict':2048}}
 save(f'{i}-request.json',request); start=time.monotonic(); raw=api('/api/chat',request);save(f'{i}-response.json',raw)
 row={'call':i,'seconds':time.monotonic()-start,'input_tokens':raw.get('prompt_eval_count'),'output_tokens':raw.get('eval_count')}
 try:
  act=json.loads(raw['message']['content']);row['action']=act;valid_action(act)
  if act['action']=='finish':row['result']={'status':'MODEL_FINISHED'};trace.append(row);break
  blob,result=probe(act);(D/f'{i}-probe-artifact.json').write_bytes(blob);row['result']=result
 except Exception as e: row['result']={'status':'HARNESS_REFUSED','validator_executed':False,'reason':str(e),'exception_type':type(e).__name__}
 trace.append(row);save('trace.json',trace)
 messages.extend([{'role':'assistant','content':raw['message']['content']},{'role':'user','content':json.dumps({'tool_result':row['result'],'calls_remaining':4-i})}])
save('trace.json',trace)
save('results.json',{'calls':len(trace),'finished':trace[-1].get('result',{}).get('status')=='MODEL_FINISHED','discovery_accepted':'PENDING_HOST_REPLAY','input_tokens':sum(x.get('input_tokens',0) or 0 for x in trace),'output_tokens':sum(x.get('output_tokens',0) or 0 for x in trace),'seconds':sum(x['seconds'] for x in trace)})
print(json.dumps(trace,ensure_ascii=False,indent=2))
